import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

// https://vite.dev/config/
export default defineConfig({
  base: './', // portable: works on GitHub Pages project path, domain root, or file preview
  plugins: [
    react(),
    tailwindcss(),
  ],
})

.counter {
  font-size: 16px;
  padding: 5px 10px;
  border-radius: 5px;
  color: var(--accent);
  background: var(--accent-bg);
  border: 2px solid transparent;
  transition: border-color 0.3s;
  margin-bottom: 24px;

  &:hover {
    border-color: var(--accent-border);
  }
  &:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

.hero {
  position: relative;

  .base,
  .framework,
  .vite {
    inset-inline: 0;
    margin: 0 auto;
  }

  .base {
    width: 170px;
    position: relative;
    z-index: 0;
  }

  .framework,
  .vite {
    position: absolute;
  }

  .framework {
    z-index: 1;
    top: 34px;
    height: 28px;
    transform: perspective(2000px) rotateZ(300deg) rotateX(44deg) rotateY(39deg)
      scale(1.4);
  }

  .vite {
    z-index: 0;
    top: 107px;
    height: 26px;
    width: auto;
    transform: perspective(2000px) rotateZ(300deg) rotateX(40deg) rotateY(39deg)
      scale(0.8);
  }
}

#center {
  display: flex;
  flex-direction: column;
  gap: 25px;
  place-content: center;
  place-items: center;
  flex-grow: 1;

  @media (max-width: 1024px) {
    padding: 32px 20px 24px;
    gap: 18px;
  }
}

#next-steps {
  display: flex;
  border-top: 1px solid var(--border);
  text-align: left;

  & > div {
    flex: 1 1 0;
    padding: 32px;
    @media (max-width: 1024px) {
      padding: 24px 20px;
    }
  }

  .icon {
    margin-bottom: 16px;
    width: 22px;
    height: 22px;
  }

  @media (max-width: 1024px) {
    flex-direction: column;
    text-align: center;
  }
}

#docs {
  border-right: 1px solid var(--border);

  @media (max-width: 1024px) {
    border-right: none;
    border-bottom: 1px solid var(--border);
  }
}

#next-steps ul {
  list-style: none;
  padding: 0;
  display: flex;
  gap: 8px;
  margin: 32px 0 0;

  .logo {
    height: 18px;
  }

  a {
    color: var(--text-h);
    font-size: 16px;
    border-radius: 6px;
    background: var(--social-bg);
    display: flex;
    padding: 6px 12px;
    align-items: center;
    gap: 8px;
    text-decoration: none;
    transition: box-shadow 0.3s;

    &:hover {
      box-shadow: var(--shadow);
    }
    .button-icon {
      height: 18px;
      width: 18px;
    }
  }

  @media (max-width: 1024px) {
    margin-top: 20px;
    flex-wrap: wrap;
    justify-content: center;

    li {
      flex: 1 1 calc(50% - 8px);
    }

    a {
      width: 100%;
      justify-content: center;
      box-sizing: border-box;
    }
  }
}

#spacer {
  height: 88px;
  border-top: 1px solid var(--border);
  @media (max-width: 1024px) {
    height: 48px;
  }
}

.ticks {
  position: relative;
  width: 100%;

  &::before,
  &::after {
    content: '';
    position: absolute;
    top: -4.5px;
    border: 5px solid transparent;
  }

  &::before {
    left: 0;
    border-left-color: var(--border);
  }
  &::after {
    right: 0;
    border-right-color: var(--border);
  }
}

import React from 'react';
import { SimulationProvider, useSimulation } from './context/SimulationContext';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Sandbox from './components/Sandbox';
import Archives from './components/Archives';
import Calculator from './components/Calculator';
import Settings from './components/Settings';

const MainAppContent = () => {
  const { activeTab, themeMode } = useSimulation();

  // Mode dependent CSS classes
  const getAppClasses = () => {
    switch (themeMode) {
      case 'academic':
        return 'bg-slate-950 text-slate-300 bg-grid-green font-sans';
      case 'classified':
        return 'bg-[#020204] text-cyber-amber bg-grid-amber crt-overlay scanline-amber font-mono';
      case 'sci-fi':
      default:
        return 'bg-[#05070f] text-cyber-text bg-grid-cyber crt-overlay scanline font-mono';
    }
  };

  const renderActiveModule = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard />;
      case 'sandbox':
        return <Sandbox />;
      case 'archives':
        return <Archives />;
      case 'calculator':
        return <Calculator />;
      case 'settings':
        return <Settings />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className={`flex h-screen w-screen overflow-hidden relative select-none ${getAppClasses()}`}>

      {/* Ambient glowing particles or indicators in background */}
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-indigo-950/15 via-transparent to-transparent pointer-events-none z-0" />

      {/* Left Collapsible Navigation Sidebar */}
      <Sidebar />

      {/* Main Simulation View Area */}
      <main className="flex-1 h-screen overflow-hidden flex flex-col relative z-10 bg-transparent">
        {renderActiveModule()}
      </main>

    </div>
  );
};

function App() {
  return (
    <SimulationProvider>
      <MainAppContent />
    </SimulationProvider>
  );
}

export default App;

@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;700&family=Orbitron:wght@400;500;700;900&display=swap');

@import "tailwindcss";

@theme {
  --color-cyber-bg: #05070f;
  --color-cyber-obsidian: #020306;
  --color-cyber-dark: #0a0d18;
  --color-cyber-blue: #00f0ff;
  --color-cyber-green: #00ff87;
  --color-cyber-amber: #ffaa00;
  --color-cyber-red: #ff0055;
  --color-cyber-text: #a0aec0;
  --color-cyber-grid: rgba(0, 240, 255, 0.04);

  --font-mono: "JetBrains Mono", Fira Code, Courier New, monospace;
  --font-orbitron: "Orbitron", sans-serif;

  --animate-scanline: scanline 10s linear infinite;
  --animate-flicker: flicker 0.3s ease-in-out infinite;
  --animate-pulse-slow: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  --animate-glow-blue: glow-blue 2.5s ease-in-out infinite;
  --animate-glow-green: glow-green 2.5s ease-in-out infinite;
  --animate-spin-slow: spin 15s linear infinite;

  @keyframes scanline {
    0% { transform: translateY(-100%); }
    100% { transform: translateY(100%); }
  }
  @keyframes flicker {
    0%, 100% { opacity: 0.99; }
    50% { opacity: 0.96; }
  }
  @keyframes glow-blue {
    0%, 100% { filter: drop-shadow(0 0 2px rgba(0, 240, 255, 0.4)); }
    50% { filter: drop-shadow(0 0 10px rgba(0, 240, 255, 0.8)); }
  }
  @keyframes glow-green {
    0%, 100% { filter: drop-shadow(0 0 2px rgba(0, 255, 135, 0.4)); }
    50% { filter: drop-shadow(0 0 10px rgba(0, 255, 135, 0.8)); }
  }
}

@layer base {
  body {
    @apply bg-cyber-bg text-cyber-text font-mono antialiased overflow-hidden select-none;
    color-scheme: dark;
  }

  /* Custom Scrollbar for Sci-Fi Terminals */
  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }
  ::-webkit-scrollbar-track {
    background: rgba(2, 3, 6, 0.5);
    border-left: 1px solid rgba(0, 240, 255, 0.1);
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(0, 240, 255, 0.3);
    border-radius: 3px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: rgba(0, 240, 255, 0.6);
    box-shadow: 0 0 8px rgba(0, 240, 255, 0.5);
  }
}

/* Custom Sci-Fi UI utilities */
.bg-grid-cyber {
  background-image: 
    linear-gradient(to right, rgba(0, 240, 255, 0.03) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0, 240, 255, 0.03) 1px, transparent 1px);
  background-size: 32px 32px;
  background-position: center;
}

.bg-grid-green {
  background-image: 
    linear-gradient(to right, rgba(0, 255, 135, 0.02) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0, 255, 135, 0.02) 1px, transparent 1px);
  background-size: 32px 32px;
  background-position: center;
}

.bg-grid-amber {
  background-image: 
    linear-gradient(to right, rgba(255, 170, 0, 0.025) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 170, 0, 0.025) 1px, transparent 1px);
  background-size: 24px 24px;
  background-position: center;
}

/* CRT Scanlines and flicker */
.crt-overlay {
  position: relative;
  overflow: hidden;
}

.crt-overlay::after {
  content: " ";
  display: block;
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  right: 0;
  background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.3) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.03), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.03));
  z-index: 9999;
  background-size: 100% 3px, 3px 100%;
  pointer-events: none;
}

.scanline::before {
  content: '';
  position: absolute;
  width: 100%;
  height: 100px;
  background: linear-gradient(to bottom, rgba(0, 240, 255, 0), rgba(0, 240, 255, 0.08) 50%, rgba(0, 240, 255, 0));
  animation: scanline 6s linear infinite;
  pointer-events: none;
  z-index: 10;
}

.scanline-amber::before {
  content: '';
  position: absolute;
  width: 100%;
  height: 100px;
  background: linear-gradient(to bottom, rgba(255, 170, 0, 0), rgba(255, 170, 0, 0.08) 50%, rgba(255, 170, 0, 0));
  animation: scanline 8s linear infinite;
  pointer-events: none;
  z-index: 10;
}

/* Custom cyber corners & panel borders */
.cyber-panel {
  position: relative;
  background: rgba(5, 7, 15, 0.75);
  border: 1px solid rgba(0, 240, 255, 0.15);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.5), inset 0 0 12px rgba(0, 240, 255, 0.03);
  backdrop-filter: blur(8px);
}

.cyber-panel-green {
  position: relative;
  background: rgba(2, 3, 6, 0.8);
  border: 1px solid rgba(0, 255, 135, 0.15);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.5), inset 0 0 12px rgba(0, 255, 135, 0.02);
  backdrop-filter: blur(8px);
}

.cyber-panel-amber {
  position: relative;
  background: rgba(6, 4, 1, 0.9);
  border: 1px solid rgba(255, 170, 0, 0.2);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.7), inset 0 0 12px rgba(255, 170, 0, 0.03);
  backdrop-filter: blur(4px);
}

/* Cyber cut-corners decorator */
.cyber-corners::before {
  content: '';
  position: absolute;
  top: -1px;
  left: -1px;
  width: 8px;
  height: 8px;
  border-top: 2px solid currentColor;
  border-left: 2px solid currentColor;
}

.cyber-corners::after {
  content: '';
  position: absolute;
  bottom: -1px;
  right: -1px;
  width: 8px;
  height: 8px;
  border-bottom: 2px solid currentColor;
  border-right: 2px solid currentColor;
}

/* Interactive redacted text */
.redacted {
  background-color: #111;
  color: #111;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  padding: 0 2px;
  border-radius: 2px;
}

.redacted:hover {
  background-color: rgba(255, 255, 255, 0.08);
  color: inherit;
  text-shadow: 0 0 4px currentColor;
}

.redacted-revealed {
  background-color: transparent !important;
  color: inherit !important;
  border-bottom: 1px dashed rgba(255, 255, 255, 0.2);
}

/* Cyber buttons styling */
.btn-cyber {
  position: relative;
  overflow: hidden;
  transition: all 0.2s ease;
  clip-path: polygon(6px 0%, 100% 0%, 100% calc(100% - 6px), calc(100% - 6px) 100%, 0% 100%, 0% 6px);
}

.btn-cyber::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.15),
    transparent
  );
  transition: 0.5s;
}

.btn-cyber:hover::before {
  left: 100%;
}

/* Digital grid values scanning animation */
@keyframes sweep {
  0% {
    transform: translateY(-100%);
  }
  100% {
    transform: translateY(100%);
  }
}

.sweep-line {
  position: absolute;
  width: 100%;
  height: 2px;
  background: linear-gradient(to right, transparent, rgba(0, 240, 255, 0.4), transparent);
  animation: sweep 3s linear infinite;
  pointer-events: none;
}

