              {/* Distance Input */}
              <div className="space-y-1.5">
                <label className="text-[10px] text-gray-500 uppercase tracking-wider block font-bold">Distance Altitude (meters)</label>
                <input
                  type="number"
                  min="1"
                  max="100"
                  value={calcDist}
