              </div>

            </div>

            {/* Sync button to load active values from sandbox */}
            <button
              onClick={() => { setCalcMass(simMass); setCalcDist(simDist); setCalcFreq(simFreq); playClick(); addNotification("Loaded current simulation parameters into calculator."); }}
              className="text-[9px] text-gray-500 hover:text-white uppercase tracking-widest border border-gray-800 px-2 py-1 rounded w-fit self-start transition-colors"
            >
              Sync Current Simulation Parameters
            </button>

            {/* Mathematical Step-by-Step Solver */}
            <div className="mt-6 border-t border-gray-900 pt-4 space-y-2.5">
              <span className="text-[10px] text-gray-500 uppercase tracking-wider block font-bold">Calculations Breakdown</span>
              <div className="bg-[#020204] border border-gray-900 rounded p-3 text-[10px] font-mono space-y-1.5 text-gray-400">
                <div>1. Gravity Downward Force: <span className="text-white">{`\\(F_g = ${calcMass} \\cdot 9.81 \\text{ m/s}^2 = ${(calcMass * 9.81).toFixed(1)} \\text{ N}\\)`}</span></div>
                <div>2. Ideal Resonance Peak: <span className="text-white">{`\\(f_{res} = 3.5 \\cdot ${calcMass} + 14 \\cdot ${calcDist} = ${localTargetFrequency} \\text{ Hz}\\)`}</span></div>
                <div>3. Wave Alignment Factor: <span className={`font-semibold ${resonanceFactor > 0.8 ? 'text-cyber-green' : 'text-cyber-amber'}`}>{`\\(\\eta_{wave} = ${resonanceFactor} \\ (${(resonanceFactor*100).toFixed(1)}\\%)\\)`}</span></div>
                <div>4. Distance Attenuation Squared: <span className="text-white">{`\\(d^2 = ${calcDist * calcDist} \\text{ m}^2\\)`}</span></div>
                <div className="border-t border-gray-900 pt-1.5 mt-1.5 text-xs">
                  Required Neg Energy: <span className={`font-bold ${theme.accent}`}>{`\\(E_{req} = \\frac{${calcLift} \\cdot ${calcDist * calcDist}}{12 \\cdot ${resonanceFactor}} = ${requiredEnergy} \\text{ eV}\\)`}</span>
                </div>
              </div>
            </div>

          </div>
        </div>

        {/* Sync into Sandbox button */}
        <div className="mt-8">
          <button
            onClick={() => { setShowReport(true); playClick(); }}
            className={`w-full py-2.5 rounded font-orbitron font-bold text-xs tracking-widest transition-all duration-200 ${theme.accentBg}`}
          >
            GENERATE SIMULATION REPORT
          </button>
        </div>

      </div>

      {/* Column 2: Calculated Outputs & Report Viewer */}
      <div className={`cyber-panel border ${theme.border} bg-cyber-obsidian/75 p-5 flex flex-col justify-between relative`}>

        {/* Results Card */}
        <div>
          <div className="flex justify-between items-center border-b border-gray-900 pb-3 mb-6">
            <h2 className="font-orbitron text-xs font-bold tracking-widest uppercase text-white flex items-center gap-2">
              <FileSpreadsheet className="w-4 h-4 text-cyber-blue" />
              System Power Projection
            </h2>
            <span className="text-[9px] text-gray-500 font-mono">OUTPUT TELEMETRY</span>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

            {/* Required Energy Card */}
            <div className="border border-gray-900 bg-gray-950/80 p-4 rounded text-center space-y-1">
              <span className="text-[9px] text-gray-500 uppercase tracking-widest block">Required Energy Field</span>
              <span className={`text-3xl font-orbitron font-black ${theme.accent}`}>{requiredEnergy} eV</span>
              <span className="text-[10px] text-gray-500 block">Negative energy charge</span>
            </div>

            {/* Projected Power Card */}
            <div className="border border-gray-900 bg-gray-950/80 p-4 rounded text-center space-y-1">
              <span className="text-[9px] text-gray-500 uppercase tracking-widest block">Projected Grid Power</span>
              <span className="text-3xl font-orbitron font-black text-white">{projectedPower} GW</span>
              <span className="text-[10px] text-gray-500 block">Estimated generator draw</span>
            </div>

          </div>

          {/* Resonance warnings */}
          {resonanceFactor < 0.6 && (
            <div className="mt-6 p-3 rounded border border-cyber-red/30 bg-cyber-red/5 text-[11px] text-cyber-red flex items-start gap-2 font-mono">
              <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" />
              <span>
                <strong>DANGER: Low Wave Alignment ({(resonanceFactor*100).toFixed(1)}%).</strong> 
                The current frequency ({calcFreq} Hz) deviates significantly from the target resonance peak ({localTargetFrequency} Hz). This inefficiency requires extreme power grid draw ({projectedPower} GW) and risks capacitor breakdown.
              </span>
            </div>
          )}

          {resonanceFactor >= 0.9 && (
            <div className="mt-6 p-3 rounded border border-cyber-green/30 bg-cyber-green/5 text-[11px] text-cyber-green flex items-start gap-2 font-mono">
              <Check className="w-4 h-4 flex-shrink-0 mt-0.5" />
              <span>
                <strong>COHERENT RESONANCE LOCK ({(resonanceFactor*100).toFixed(1)}%).</strong> 
                The frequency configuration matches the gravitational lattice load. Wave attenuation is optimal. Required negative energy is minimized.
              </span>
            </div>
          )}

        </div>

        {/* Diagnostic info at bottom */}
        <div className="mt-8 border-t border-gray-900 pt-4 text-[10px] font-mono text-gray-500 leading-relaxed">
          <p>This calculator processes classical and relativistic metric forces: Casimir plate separation, asymmetric electrostatic lift, and quantum vacuum drag tensors. Use calculated settings in the Theoretical Hub to verify levitation coefficients.</p>
        </div>

      </div>

      {/* Floating Report Modal Overlay */}
      {showReport && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className={`cyber-panel border ${theme.border} bg-cyber-obsidian w-full max-w-xl p-5 space-y-4`}>
            <div className="flex justify-between items-center border-b border-gray-900 pb-2">
              <span className="font-orbitron text-xs font-bold tracking-widest text-white uppercase">Generated Classified Telemetry Report</span>
              <button 
                onClick={() => setShowReport(false)}
                className="text-gray-500 hover:text-white text-xs font-mono border border-gray-800 px-1.5 py-0.5 rounded"
              >
                CLOSE [ESC]
              </button>
            </div>

            <pre className="bg-black text-[10px] p-4 border border-gray-900 rounded font-mono text-cyber-green select-all leading-relaxed whitespace-pre overflow-x-auto max-h-[300px] scrollbar-thin">
              {reportString}
            </pre>

            <div className="flex gap-2">
              <button
                onClick={() => handleCopyReport(reportString)}
                className="flex-1 py-2 bg-gray-900 hover:bg-gray-800 text-white rounded font-mono text-xs flex items-center justify-center gap-2 border border-gray-800 transition-colors"
              >
                {copied ? <Check className="w-4 h-4 text-cyber-green" /> : <Copy className="w-4 h-4" />}
                {copied ? "COPIED TO CLIPBOARD" : "COPY TELEMETRY TEXT"}
              </button>

              <button
                onClick={handlePrint}
                className={`py-2 px-4 rounded font-mono text-xs flex items-center justify-center gap-2 transition-all ${theme.badge} hover:text-white`}
              >
                <Printer className="w-4 h-4" />
                PRINT / PDF
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default Calculator;

import React, { useEffect, useRef, useState } from 'react';
import { useSimulation } from '../context/SimulationContext';
import { 
  Zap, 
  HelpCircle, 
  RefreshCw, 
  CheckCircle,
  AlertTriangle,
  ArrowUp,
  ArrowDown
} from 'lucide-react';
import confetti from 'canvas-confetti';

const Sandbox = () => {
  const {
    themeMode,
    mass,
    setMass,
    energy,
    setEnergy,
    frequency,
    setFrequency,
    distance,
    setDistance,
    gmi,
    stability,
    negMassDensity,
    power,
    levitationStatus,
    targetFrequency,
    addNotification,
    playSuccess,
    playWarning,
    playClick
  } = useSimulation();

  const canvasRef = useRef(null);
  const successPlayedRef = useRef(false);

  // Auto-tune frequency helper
  const handleAutoTune = () => {
    setFrequency(targetFrequency);
    playClick();
    addNotification(`Automatic Resonance Tune engaged: Frequency set to ${targetFrequency} Hz.`);
  };

  // Play success chime when stability is achieved
  useEffect(() => {
    if (levitationStatus === 'STABLE') {
      if (!successPlayedRef.current) {
        playSuccess();
        successPlayedRef.current = true;
        // Explode minor cyber green/blue confetti!
        confetti({
          particleCount: 50,
          spread: 60,
          origin: { y: 0.6 },
          colors: ['#00f0ff', '#00ff87', '#0f172a']
        });
      }
    } else {
      successPlayedRef.current = false;
    }
  }, [levitationStatus]);

  // Color mappings
  const getColors = () => {
    switch (themeMode) {
      case 'academic':
        return {
          accent: 'text-emerald-400',
          accentBg: 'bg-emerald-500',
          accentBorder: 'border-emerald-800/40',
          sliderThumb: 'accent-emerald-500',
          canvasGlow: 'rgba(16, 185, 129, ',
          textLabel: 'text-slate-400'
        };
      case 'classified':
        return {
          accent: 'text-cyber-amber',
          accentBg: 'bg-cyber-amber',
          accentBorder: 'border-cyber-amber/30',
          sliderThumb: 'accent-cyber-amber',
          canvasGlow: 'rgba(255, 170, 0, ',
          textLabel: 'text-amber-600/70'
        };
      case 'sci-fi':
      default:
        return {
          accent: 'text-cyber-blue',
          accentBg: 'bg-cyber-blue',
          accentBorder: 'border-cyber-blue/25',
          sliderThumb: 'accent-cyber-blue',
          canvasGlow: 'rgba(0, 240, 255, ',
          textLabel: 'text-gray-500'
        };
    }
  };

  const colors = getColors();

  // Draw simulation physics sandbox on Canvas
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let animationId;
    let time = 0;

    // Set canvas dimensions
    const resizeCanvas = () => {
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * window.devicePixelRatio;
      canvas.height = rect.height * window.devicePixelRatio;
      ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
    };
    resizeCanvas();

    // Particle class for energy streams
    class Particle {
      constructor() {
        this.reset();
        this.y = Math.random() * (canvas.height / window.devicePixelRatio);
      }
      reset() {
        const w = canvas.width / window.devicePixelRatio;
        const h = canvas.height / window.devicePixelRatio;
        this.x = Math.random() * w;
        this.y = h + Math.random() * 40; // start at bottom
        this.speed = 1 + Math.random() * 2.5;
        this.size = 0.5 + Math.random() * 1.5;
        this.alpha = 0.1 + Math.random() * 0.5;
      }
      update(levStatus, energyVal) {
        const h = canvas.height / window.devicePixelRatio;

        // Speed proportional to negative energy
        this.y -= this.speed * (0.3 + (energyVal / 300));

        // Horizontal jitter
        this.x += Math.sin(this.y * 0.05) * 0.5;

        // Reset if goes off top
        if (this.y < 0) {
          this.reset();
        }
      }
      draw(cCtx, themeType) {
        cCtx.save();
        cCtx.globalAlpha = this.alpha;
        if (themeType === 'classified') {
          cCtx.fillStyle = '#ffaa00';
        } else if (themeType === 'academic') {
          cCtx.fillStyle = '#34d399';
        } else {
          cCtx.fillStyle = '#00ff87'; // green-ish negative energy flow
        }
        cCtx.beginPath();
        cCtx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        cCtx.fill();
        cCtx.restore();
      }
    }

    const particles = Array.from({ length: 45 }, () => new Particle());

    // Main animation loop
    const render = () => {
      time += 0.04;
      const w = canvas.width / window.devicePixelRatio;
      const h = canvas.height / window.devicePixelRatio;

      // Clear with obsidian background
      ctx.fillStyle = '#020306';
      ctx.fillRect(0, 0, w, h);

      // Render Gravity Wave Particles (if mass is high, draw downward gravity ripples)
      particles.forEach(p => {
        p.update(levitationStatus, energy);
        p.draw(ctx, themeMode);
      });

      // 1. Draw Space-Time Grid Warping
      // Draw grid lines that bend around the center capsule based on GMI and Mass
      const gridSpacing = 24;
      const capsuleX = w / 2;

      // Calculate target Y coordinate of capsule
      let targetCapsuleY = h - 40; // crashed
      if (levitationStatus === 'STABLE') {
        // stable float
        targetCapsuleY = h / 2 + Math.sin(time * 1.5) * 6;
      } else if (levitationStatus === 'UNSTABLE') {
        // unstable float - shakes & jumps
        const shake = (Math.random() - 0.5) * 6;
        targetCapsuleY = h / 2 - 20 + Math.sin(time * 6) * 18 + shake;
      }

      // Interpolate capsule drawing position (smooth drift)
      const currentCapsuleY = targetCapsuleY;

      ctx.strokeStyle = themeMode === 'classified' 
        ? 'rgba(255, 170, 0, 0.05)' 
        : themeMode === 'academic'
        ? 'rgba(16, 185, 129, 0.04)'
        : 'rgba(0, 240, 255, 0.04)';
      ctx.lineWidth = 1;

      // Vertical grid lines
      for (let x = 0; x < w; x += gridSpacing) {
        ctx.beginPath();
        for (let y = 0; y < h; y += 4) {
          // Calculate grid node displacement from capsule
          const dx = x - capsuleX;
          const dy = y - currentCapsuleY;
          const distSq = dx * dx + dy * dy;
          const dist = Math.sqrt(distSq);

          // Force factor of warping
          const warpForce = (gmi * 45) + (mass * 0.05);
          const warpRadius = 110;

          let offsetX = 0;
          if (dist < warpRadius && dist > 1) {
            const ratio = (warpRadius - dist) / warpRadius; // 1 at center, 0 at boundary
            offsetX = dx * ratio * (warpForce / 120);
          }

          if (y === 0) {
            ctx.moveTo(x - offsetX, y);
          } else {
            ctx.lineTo(x - offsetX, y);
          }
        }
        ctx.stroke();
      }

      // Horizontal grid lines
      for (let y = 0; y < h; y += gridSpacing) {
        ctx.beginPath();
        for (let x = 0; x < w; x += 4) {
          const dx = x - capsuleX;
          const dy = y - currentCapsuleY;
          const dist = Math.sqrt(dx * dx + dy * dy);

          const warpForce = (gmi * 45) + (mass * 0.05);
          const warpRadius = 110;

          let offsetY = 0;
          if (dist < warpRadius && dist > 1) {
            const ratio = (warpRadius - dist) / warpRadius;
            offsetY = dy * ratio * (warpForce / 120);
          }

          if (x === 0) {
            ctx.moveTo(x, y - offsetY);
          } else {
            ctx.lineTo(x, y - offsetY);
          }
        }
        ctx.stroke();
      }

      // 2. Draw Anti-Gravity Field Waves (Glowing rings around levitation core)
      if (levitationStatus !== 'CRASHED') {
        ctx.save();
        const glowOpacity = levitationStatus === 'STABLE' ? 0.2 + Math.abs(Math.sin(time * 2)) * 0.15 : 0.4 + Math.random() * 0.2;
        const glowColor = themeMode === 'classified' ? '255, 170, 0' : themeMode === 'academic' ? '16, 185, 129' : '0, 240, 255';

        ctx.shadowBlur = levitationStatus === 'STABLE' ? 20 : 35;
        ctx.shadowColor = `rgba(${glowColor}, 0.8)`;

        ctx.strokeStyle = `rgba(${glowColor}, ${glowOpacity})`;
        ctx.lineWidth = 2;

        // Draw multiple resonance field rings
        const ringCount = levitationStatus === 'STABLE' ? 3 : 4;
        for (let r = 0; r < ringCount; r++) {
          const radius = 25 + r * 15 + (Math.sin(time * 3 + r) * 4);
          ctx.beginPath();
          ctx.arc(capsuleX, currentCapsuleY, radius, 0, Math.PI * 2);
          ctx.stroke();
        }
        ctx.restore();
      }

      // 3. Draw Levitating Capsule / Vehicle (Sci-Fi saucer/pod design)
      ctx.save();

      // Shadow glow for the capsule itself
      if (levitationStatus === 'STABLE') {
        ctx.shadowBlur = 15;
        ctx.shadowColor = themeMode === 'classified' ? '#ffaa00' : themeMode === 'academic' ? '#10b981' : '#00f0ff';
      } else if (levitationStatus === 'UNSTABLE') {
        ctx.shadowBlur = 25;
        ctx.shadowColor = '#ffaa00'; // Amber alert
      } else {
        ctx.shadowBlur = 0;
      }

      const accentHex = themeMode === 'classified' ? '#ffaa00' : themeMode === 'academic' ? '#10b981' : '#00f0ff';
      ctx.fillStyle = '#111827';
      ctx.strokeStyle = accentHex;
      ctx.lineWidth = 2;

      // Draw reactor capsule (futuristic diamond-wing silhouette)
      ctx.beginPath();
      ctx.moveTo(capsuleX - 25, currentCapsuleY + 5);
      ctx.lineTo(capsuleX - 35, currentCapsuleY - 5);
      ctx.lineTo(capsuleX - 10, currentCapsuleY - 12);
      ctx.lineTo(capsuleX + 10, currentCapsuleY - 12);
      ctx.lineTo(capsuleX + 35, currentCapsuleY - 5);
      ctx.lineTo(capsuleX + 25, currentCapsuleY + 5);
      ctx.lineTo(capsuleX + 15, currentCapsuleY + 12);
      ctx.lineTo(capsuleX - 15, currentCapsuleY + 12);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();

      // Core thruster / emitter node (glow dot)
      ctx.beginPath();
      ctx.arc(capsuleX, currentCapsuleY, 5, 0, Math.PI * 2);
      ctx.fillStyle = levitationStatus === 'STABLE' 
        ? (themeMode === 'classified' ? '#ffaa00' : themeMode === 'academic' ? '#34d399' : '#00f0ff')
        : levitationStatus === 'UNSTABLE'
        ? '#ffaa00'
        : '#ff0055';
      ctx.fill();
      ctx.restore();

      // Draw force vector indicators (arrows showing gravity vs lift)
      if (levitationStatus !== 'CRASHED') {
        ctx.lineWidth = 1.5;
        const arrowOffset = 20;

        // Lift Force vector (Up arrow in cyan/green)
        ctx.strokeStyle = themeMode === 'classified' ? '#ffaa00' : themeMode === 'academic' ? '#10b981' : '#00ff87';
        ctx.fillStyle = ctx.strokeStyle;
        const liftLen = Math.min(60, energy * 0.08 + gmi * 8);
        ctx.beginPath();
        ctx.moveTo(capsuleX, currentCapsuleY - arrowOffset);
        ctx.lineTo(capsuleX, currentCapsuleY - arrowOffset - liftLen);
        ctx.stroke();
        // Arrowhead
        ctx.beginPath();
        ctx.moveTo(capsuleX, currentCapsuleY - arrowOffset - liftLen - 4);
        ctx.lineTo(capsuleX - 4, currentCapsuleY - arrowOffset - liftLen);
        ctx.lineTo(capsuleX + 4, currentCapsuleY - arrowOffset - liftLen);
        ctx.closePath();
        ctx.fill();

        // Gravity Force vector (Down arrow in red/blue)
        ctx.strokeStyle = '#ff0055';
        ctx.fillStyle = ctx.strokeStyle;
        const gravLen = Math.min(60, mass * 0.04 + (50 - distance) * 0.2);
        ctx.beginPath();
        ctx.moveTo(capsuleX, currentCapsuleY + arrowOffset);
        ctx.lineTo(capsuleX, currentCapsuleY + arrowOffset + gravLen);
        ctx.stroke();
        // Arrowhead
        ctx.beginPath();
        ctx.moveTo(capsuleX, currentCapsuleY + arrowOffset + gravLen + 4);
        ctx.lineTo(capsuleX - 4, currentCapsuleY + arrowOffset + gravLen);
        ctx.lineTo(capsuleX + 4, currentCapsuleY + arrowOffset + gravLen);
        ctx.closePath();
        ctx.fill();

        // Label arrows
        ctx.font = '8px monospace';
        ctx.fillStyle = '#fff';
        ctx.fillText(`F_lift: ${(energy * 0.15).toFixed(1)} N`, capsuleX + 8, currentCapsuleY - arrowOffset - (liftLen/2));
        ctx.fillText(`F_grav: ${(mass * 9.8).toFixed(0)} N`, capsuleX + 8, currentCapsuleY + arrowOffset + (gravLen/2));
      }

      // 4. Critical Collapse Text Overlay (if crashed)
      if (levitationStatus === 'CRASHED') {
        ctx.fillStyle = 'rgba(255, 0, 85, 0.08)';
        ctx.fillRect(0, 0, w, h);

        ctx.font = 'bold 12px Orbitron';
        ctx.fillStyle = '#ff0055';
        ctx.textAlign = 'center';
        ctx.fillText("CRITICAL FIELD COLLAPSE", w / 2, h / 2 - 25);
        ctx.font = '8px monospace';
        ctx.fillStyle = '#9b0b30';
        ctx.fillText("INSUFFICIENT LIFT FORCE OR TUNING FREQUENCY OUT OF RANGE", w / 2, h / 2 - 12);

        // Render spark explosions on base
        ctx.fillStyle = '#ff5500';
        for (let i = 0; i < 5; i++) {
          const sparkX = capsuleX + (Math.random() - 0.5) * 40;
          const sparkY = currentCapsuleY + 12 + Math.random() * 4;
          ctx.beginPath();
          ctx.arc(sparkX, sparkY, 1 + Math.random() * 2, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      animationId = requestAnimationFrame(render);
    };

    render();

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [mass, energy, frequency, distance, gmi, stability, levitationStatus, themeMode]);

  return (
    <div className="p-6 grid grid-cols-1 xl:grid-cols-3 gap-6 overflow-y-auto h-full max-h-screen select-none">

      {/* Physics Sandbox Environment Visualizer */}
      <div className="xl:col-span-2 flex flex-col gap-4">

        {/* Canvas Card */}
        <div className={`cyber-panel border ${colors.accentBorder} bg-gray-950/60 p-2 flex flex-col relative h-[380px]`}>
          <div className="flex justify-between items-center px-3 py-2 border-b border-gray-900 text-[10px] uppercase font-bold tracking-widest text-white">
            <span className="flex items-center gap-1.5">
              <span className={`h-2 w-2 rounded-full ${
